PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, actor TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY,name TEXT NOT NULL,synthetic INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS assessments (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),name TEXT NOT NULL,language_id TEXT NOT NULL,stage TEXT NOT NULL DEFAULT 'prepare',synthetic INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS grants (actor TEXT NOT NULL,scope_type TEXT NOT NULL,scope_id TEXT NOT NULL,role TEXT NOT NULL,PRIMARY KEY(actor,scope_type,scope_id));
CREATE TABLE IF NOT EXISTS surveys (id TEXT PRIMARY KEY,assessment_id TEXT NOT NULL REFERENCES assessments(id),template_id TEXT NOT NULL,template_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS access_codes (id TEXT PRIMARY KEY,survey_id TEXT NOT NULL REFERENCES surveys(id),code TEXT NOT NULL UNIQUE,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS participants (id TEXT PRIMARY KEY,survey_id TEXT NOT NULL REFERENCES surveys(id),access_id TEXT NOT NULL UNIQUE REFERENCES access_codes(id),token TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS submissions (id TEXT PRIMARY KEY,participant_id TEXT NOT NULL UNIQUE REFERENCES participants(id),survey_id TEXT NOT NULL REFERENCES surveys(id),answers TEXT NOT NULL,digest TEXT NOT NULL,idempotency_key TEXT NOT NULL,receipt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS intents (id TEXT PRIMARY KEY,actor TEXT NOT NULL,survey_id TEXT NOT NULL,expires_at INTEGER NOT NULL,receipt TEXT);
